import React, {useContext, useEffect, useState} from 'react';
import { useLocation } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import ProfileHead from './profilehead';
import { SMSIcon, WhatsappIcon } from '../common/utilitycomp';
import {getUserAlertQuotas} from '../../services/quotas/quotaService';
import { AuthContextType, AuthContext } from '../../auth/authContext';
import { IUserAlertQuota } from '../../models/quota/useralertquota';
import { CircularProgress } from '@mui/material';

const Quotas = () => {
    const[showLoading, setShowLoading] = useState<boolean>(false);
    const { user, loading } = useContext<AuthContextType|null>(AuthContext)!;
    const location = useLocation();
    const[userAlerQuota, setUserAlertQuota] = useState<IUserAlertQuota|null>(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        
       loadUserAlertQuotas();
      
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[] );

    const loadUserAlertQuotas = async () => {
        setShowLoading(true);
        var data = await getUserAlertQuotas(await user?.getIdToken());
        setUserAlertQuota(data);
        setShowLoading(false);
    }

    return (
            <div>
                <Toaster position="bottom-center" reverseOrder={false}/>
                <ProfileHead/>
                <div className='content-margin mt-3'>
                    <div className='card col-md-6'>
                        <div className='card-header'>
                           <div className='row'>
                           <div className="col-6 d-flex align-items-center"><h6 className="mb-0">Alert Quotas &nbsp;
                             {showLoading && <CircularProgress className='spinner'/>}
                            </h6></div>
                           <div className="col-6 text-end">
                           <a className="url link " href='#/alerthistory'> view alert history</a>
                    </div>
                           </div>
                        </div>
                        <div className='card-body'>
                            <table className="table align-items-center mb-0">
                            <thead>
                                <tr>
                                <th>
                                <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Alert channel</div>
                                </th>
                                <th>
                                <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Quotas</div>
                                </th>
                                <th>
                                <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Remaining</div>
                                </th>
                                </tr>
                            </thead>
                            <tbody>
                                    <tr>
                                        <td><SMSIcon/> sms</td>
                                        <td>{userAlerQuota?.monthlySMSQuota}</td>
                                        <td> {userAlerQuota?.monthlySMSQuotaRemaining}</td>
                                    </tr>
                                    <tr>
                                          <td><WhatsappIcon/> whatsapp</td>
                                          <td>{userAlerQuota?.monthlyWhatsappQuota}</td>
                                          <td> {userAlerQuota?.monthlyWhatsappQuotaRemaining}</td>
                                        </tr>
                            </tbody>
                            </table>
                        </div>
                    </div>
                
                </div>
            </div>
    )
}

export default Quotas;
