interface EnhancedTableProps {
  numSelected: number;
  onRequestSort: (
    event: React.MouseEvent<unknown>,
    property: keyof IAnnouncement
  ) => void;
  onSelectAllClick: (event: React.ChangeEvent<HTMLInputElement>) => void;
  order: Order;
  orderBy: string;
  rowCount: number;
  filterByStock?: string;
}

function EnhancedTableHead(props: EnhancedTableProps) {
  const {
    order,
    orderBy,
    onRequestSort,
    filterByStock,
  } = props;
  const createSortHandler =
    (property: keyof IAnnouncement) => (event: React.MouseEvent<unknown>) => {
      onRequestSort(event, property);
    };

  return (
    <TableHead>
      <TableRow>
        {headCells.filter(a => !filterByStock || a.id !== 'stockCode').map((headCell) =>
        (
          <TableCell
            key={headCell.id}
            align={'left'}
            padding={headCell.disablePadding ? 'none' : 'normal'}
            sortDirection={orderBy === headCell.id ? order : false}
          >
           {headCell.enableSort &&  <TableSortLabel
              active={orderBy === headCell.id}
              direction={orderBy === headCell.id ? order : 'asc'}
              onClick={createSortHandler(headCell.id)}
            >
              <div className='text-uppercase text-primary text-xxs font-weight-bolder opacity-7'>
                {headCell.label}
              </div>
              {orderBy === headCell.id ? (
                <Box component="span" sx={visuallyHidden}>
                  {order === 'desc' ? 'sorted descending' : 'sorted ascending'}
                </Box>
              ) : null}
            </TableSortLabel>
           }

           {
            !headCell.enableSort && 
            <div className='text-uppercase text-primary text-xxs font-weight-bolder opacity-7'>
                {headCell.label}
                  {headCell.id === 'aiSummary' && <img alt="AI" title="Some of the summaries are AI generated" className='text-sm avatar-img-sm ml-5' src="https://cdn-icons-png.flaticon.com/128/9078/9078604.png"></img>}
              </div>
           }
          </TableCell>
        ))}
      </TableRow>
    </TableHead>
  );
}

