import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs from 'dayjs';
import React, {useEffect, useState} from 'react';
import { stocks, categories, impressions } from '../../models/contants/contants';
import IAnnouncementRequest from '../../models/announcement/announcementRequest';
import IStockLookup from '../../models/common/lookup';
import ILookup from '../../models/common/lookup';
import IAnnouncement, { AnnouncementCategory, AnnouncementImpression } from '../../models/announcement/announcement';
import axios from 'axios';
import { Box, CircularProgress, LinearProgress, ThemeProvider } from '@mui/material';
import { backend } from '../../models/contants/contants';
import AnnouncementTableComponent from './announcementTableComponent';
import toast, { Toaster } from 'react-hot-toast';
import { muiTheme, muiTheme1 } from '../common/muicomp';
import { strJoin } from '../../utility/utility';
import AnnouncementTableComponentMobile from './announcementTableComponentMobile';
import {isMobile} from 'react-device-detect';

const AnnouncementsComp = (props:IAnnouncementCompProps) => {
    const [showLoading,setShowLoading] = useState<boolean>(false);
    const [filterText,setFilterText] = useState<string>('');

    var fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - 1);

    const initAnnnouncementRequest:IAnnouncementRequest = {
        stockcodes: [],
        categories:[],
        impressions:[AnnouncementImpression.positive],
        fromDate: fromDate,
        toDate:new Date()};

        if(props.filterbyStock){
          initAnnnouncementRequest.stockcodes.push(props.filterbyStock);
          var result = new Date();
          result.setDate(result.getDate() - 89);
          initAnnnouncementRequest.fromDate = result;
        }
        
    const [annnouncementRequest, setAnnoncementRequest] = 
    useState<IAnnouncementRequest>(initAnnnouncementRequest);
    const [announcements, setAnnouncements] = useState<IAnnouncement[]>([]);

    const loadAnnouncements = async () => {
      setAnnouncements([]);
        setShowLoading(true);
        await axios({
            // Endpoint to send files
            url: backend+"announcements",
            method: "Post",
            headers: {
                // Add any auth token here
                authorization: "your token comes here",
            },

            // Attaching the form data
            data: annnouncementRequest,
        })
            // Handle the response from backend here
            .then((res) => {
                const data: IAnnouncement[] = res.data;
                  setAnnouncements([...data]);
                  updateFilterText(data.length);
                  setShowLoading(false);
            })
            .catch((err) => {});
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        loadAnnouncements();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    },[]);

    const onFilterStocksChange = (event:any, values:ILookup[]) => {
        setAnnoncementRequest({...annnouncementRequest, stockcodes: values.map(a=> a.code)});
    } 

    const onCategoriesChange = (event:any, values:ILookup[]) => {
        setAnnoncementRequest({...annnouncementRequest, categories: values.map(a => a.code as AnnouncementCategory)});
    } 

    const onImpressionsChange = (event:any, values:ILookup[]) => {
        setAnnoncementRequest({...annnouncementRequest, impressions: values.map(a=> a.code as AnnouncementImpression)});
    } 

    const onFromDataChange = (event:any, values:any) => {
        setAnnoncementRequest({...annnouncementRequest, fromDate: event.$d});
    }

    const onToDataChange = (event:any, values:any) => {
        setAnnoncementRequest({...annnouncementRequest, toDate: event.$d});
    }

    const updateFilterText = (len:number) => {
      let text = 'showing '+len+' ';

      text += annnouncementRequest.impressions.length > 0 ? strJoin(annnouncementRequest.impressions): '';
      text += ' announcements ';
      text += annnouncementRequest.stockcodes.length > 0 ? 'for '+ strJoin(annnouncementRequest.stockcodes): '';
      text += ' ';
      text += annnouncementRequest.categories.length > 0 ? 'in categories '+strJoin(
        categories.filter(a => annnouncementRequest.categories.filter(b => b.toString() === a.code).length > 0)
        .map(a => {return a.name})
      ): '';
      text += ' ';

      if(annnouncementRequest.toDate.toDateString() === new Date().toDateString()){
        var days: number = Math.round((+annnouncementRequest.toDate - +annnouncementRequest.fromDate)/ 1000 / 60 / 60 / 24);
        text += 'for '+(days === 0 ? 'today': 'last '+ (days+1)+' days')+' ';
      }else{
        if(annnouncementRequest.fromDate.toDateString() === annnouncementRequest.toDate.toDateString())
        text += 'on '+annnouncementRequest.fromDate.toDateString();
      else
      text += 'from '+annnouncementRequest.fromDate.toDateString()+' to '+ annnouncementRequest.toDate.toDateString();
}

      setFilterText(text);
    }
    return (
          
          <><div><Toaster/></div>
          {/* { showLoading && <Box  sx={{width: '100%' }}> <LinearProgress /></Box> } */}
          <div className='page-header'>
          <div className="row">
                <div className="col-6 align-items-center">
                  <div>
                  <h6 className="mb-0">{props.headerName ?? 'Announcements'}</h6></div>
                  
                </div>
                <div className="col-6 text-end">
                  <button className="collapsed btn btn-success btn-sm mb-0" 
                  data-bs-target="#collapseOne" aria-controls="collapseOne"
                   data-bs-toggle="collapse" data-bs-auto-close="outside" aria-expanded="false">Filter&nbsp;
                   <span className="hide material-symbols-rounded">arrow_drop_up</span>
                    <span className="collapseshow material-symbols-rounded">arrow_drop_down</span>
                   </button>
                </div>
              </div>
              <div><small className='text-secondary'>{filterText}</small></div>
          </div>
          <div className="accordion-item">
<div id="collapseOne"  className="accordion-collapse collapse" data-bs-parent="#accordionExample">
    <div className="accordion-body card">
  
  <ThemeProvider theme={muiTheme1}>
    <div className="row g-3">

      { !props.filterbyStock && 
        <div className="col-sm-3">
     
        <Autocomplete
          //  value={stocks.filter(a => props.filterbyStock || props.filterbyStock === a.code)}
           size='small'
           onChange={onFilterStocksChange}
            multiple
            id=""
            options={stocks}
            getOptionLabel={(option:IStockLookup) => option.code+' - '+option.name}
            renderInput={(params) => (
              <TextField {...params} label="filter stocks" placeholder="search by scrip code or name" />
            )}
          />
         
        </div>
      }

  <div className="col-sm-2">
  <Autocomplete
  size='small'
      multiple
      id=""
      onChange={onCategoriesChange}
      options={categories}
      getOptionLabel={(option:ILookup) => option.name}
      renderInput={(params) => (
        <TextField {...params} label="category" placeholder="select categories" />
      )}
    />
  </div>
  <div className="col-sm-2">
  
  <Autocomplete
  size='small'
      multiple
      id=""
      onChange={onImpressionsChange}
      options={impressions}
      getOptionLabel={(option:ILookup) => option.name}
      defaultValue={[impressions[0]]}
      renderInput={(params) => (
        <TextField {...params} label="impression" placeholder="select impressions" />
      )}
    />
  </div>
  <div className="col-sm-2">
  <LocalizationProvider dateAdapter={AdapterDayjs}>
      <DatePicker
      maxDate={dayjs(new Date())}
      value={dayjs(annnouncementRequest.fromDate)}
      slotProps={{ textField: { size: 'small' } }}  onChange={onFromDataChange} label="from date" defaultValue={dayjs()}
      />
    </LocalizationProvider>
  </div>
  <div className="col-sm-2">
  <LocalizationProvider dateAdapter={AdapterDayjs}>
      <DatePicker maxDate={dayjs(new Date())} slotProps={{ textField: { size: 'small' } }} onChange={onToDataChange} label="to date" defaultValue={dayjs()}/>
    </LocalizationProvider>
  </div>
  <div className="col-sm-1">
  <button onClick={loadAnnouncements} type="button" className="btn btn-outline-success mb-0  btn-sm">Search</button>
  </div>
</div>
</ThemeProvider>
    </div>
</div>
</div>


<div className={(props.isCard ? "":"page-content")+" table-responsive bg-white"}>
    {!isMobile && <AnnouncementTableComponent rows={announcements} 
    filterbyStock={props.filterbyStock}
    announcementKey={props.announcementKey}/>}

     {isMobile && <AnnouncementTableComponentMobile rows={announcements} 
    filterbyStock={props.filterbyStock}
    announcementKey={props.announcementKey}/>}

    </div>
    <div className='text-center'>
      { showLoading && <CircularProgress className='spinner'/>}
    </div>
</>)
}

export default AnnouncementsComp;
